(() => {
 'use strict';const RI=window.RI,esc=RI.esc;
 RI.registerPage('billing',{title:'اشتراک و خریدها',render(){return RI.pageHead({title:'اشتراک و خریدها',actions:'<a class="btn btn--soft" href="/dashboard/wallet/" data-go="wallet">'+RI.icon('card')+'کیف پول It</a>'})+RI.tabsHtml([['current','اشتراک من'],['plans','انتخاب دوره'],['purchases','خریدها'],['payments','پرداخت‌ها']],'current')+'<div id="billing-body"></div>';},mount(root,ctx){
  const initial=ctx.opts?.tab||new URLSearchParams(location.search).get('tab');let tab=['current','plans','purchases','payments'].includes(initial)?initial:'current',alive=true,historyOff=null;const body=root.querySelector('#billing-body');
  function current(){const b=RI.state.billing,plan=b.plan&&b.plan.end>Date.now()?b.plan:null,p=plan&&RI.PLANS[plan.id],days=plan?Math.ceil((plan.end-Date.now())/86400000):0;return '<section class="planhero"><div class="planhero__main"><h2>'+RI.icon(plan?'crown':'user')+(p?'اشتراک '+esc(p.name)+' · '+esc(p.period):'حساب رایگان')+'</h2>'+(plan?'<p>'+RI.fa(days)+' روز باقی مانده · تا '+RI.date(plan.end)+'</p><small>تمدید خودکار و برداشت خودکار نداریم.</small>':'<p>رزومه، صفحهٔ لینک و انتشار روی زیردامنه با قالب‌های رایگان در دسترس‌اند.</p>')+'</div><div class="planhero__side"><button class="btn btn--primary" type="button" '+(plan?'data-sub="'+plan.id+'"':'data-select-plans')+'>'+RI.icon(plan?'refresh':'crown')+(plan?'تمدید همین دوره':'دیدن دوره‌ها')+'</button></div></section><section class="workspace-band"><h2>تفاوت دسترسی‌ها</h2><div class="table-wrap"><table class="table"><thead><tr><th>امکان</th><th>رایگان</th><th>اشتراک فعال</th></tr></thead><tbody>'+RI.PLAN_FEATURES.map(row=>'<tr><td>'+esc(row[0])+'</td>'+[row[1],row[2]].map(value=>'<td>'+(typeof value==='boolean'?RI.icon(value?'check':'close'):esc(value))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></section><section class="workspace-band"><h2>دارایی‌های دائمی</h2><p>'+RI.fa(b.purchases.length)+' قالب، فونت یا ترکیب‌رنگ خریداری‌شده؛ خرید یک‌باره با پایان اشتراک از دست نمی‌رود.</p><a class="textlink" href="/dashboard/themes/" data-go="themes">دیدن ظاهر و قالب '+RI.icon('chevL')+'</a></section>';}
  function plans(){return '<section class="workspace-band"><h2>یک مجموعه امکانات، سه دورهٔ زمانی</h2><p class="field__hint">نام‌ها از افسانه‌های ایران گرفته شده‌اند. امکانات هر سه دوره یکسان است؛ تفاوت در مدت و مبلغ است. خرید از اعتبار It انجام می‌شود.</p><div class="plans">'+Object.values(RI.PLANS).map(p=>'<article class="plan"><h3>'+esc(p.name)+'</h3><span class="chip">'+esc(p.period)+' · '+RI.fa(p.months)+' ماه</span><div class="plan__price"><b>'+RI.fa(Math.round(p.price*(RI.commerce?.rate||2000)/2000))+'</b><span>تومان کل دوره</span></div><p class="plan__per">ماهی '+RI.priceToman(Math.round(p.price/p.months))+' · '+RI.it(p.price)+'</p><ul class="plan__list"><li>'+RI.icon('check')+'قالب‌های اشتراکی و ویژه</li><li>'+RI.icon('check')+'امضای اختصاصی یا حذف نشان</li><li>'+RI.icon('check')+'بلوک متن و تصویر در لینک‌ها</li><li>'+RI.icon('check')+'خروجی CSV آمار</li></ul><button class="btn btn--primary" type="button" data-sub="'+p.id+'">انتخاب '+esc(p.name)+RI.icon('chevL')+'</button></article>').join('')+'</div><p class="field__hint">قابلیت‌های اشتراکی تا پایان دوره فعال‌اند. پس از پایان، محتوا حذف نمی‌شود؛ ظاهر عمومی به امکانات مجاز برمی‌گردد و نمایش عمومی صفحه‌های اضافه تا تمدید متوقف می‌شود. دامنهٔ مستقل در این دوره‌ها ارائه نمی‌شود.</p></section>';}
  function paint(){historyOff?.();historyOff=null;root.querySelectorAll('[data-workspace-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.workspaceTab===tab)));if(['purchases','payments'].includes(tab)){historyOff=RI.mountHistory(body,tab==='payments'?'bank':'purchases');return;}body.innerHTML=tab==='plans'?plans():current();body.querySelectorAll('[data-sub]').forEach(b=>{if(RI.commerce?.paused.includes('subscription:'+b.dataset.sub)){b.disabled=true;b.textContent='فروش موقتاً متوقف';}});}
  RI.delegate(root,'click','[data-workspace-tab]',(e,b)=>{tab=b.dataset.workspaceTab;RI.setRouteTab(tab,'current');paint();});RI.delegate(root,'click','[data-select-plans]',()=>{tab='plans';RI.setRouteTab(tab,'current');paint();});RI.delegate(root,'click','[data-sub]',async(e,b)=>{if(b.disabled)return;b.disabled=true;try{if(await RI.subscribeFlow(b.dataset.sub)){tab='current';RI.setRouteTab(tab,'current');paint();}}finally{b.disabled=false;}});
  paint();RI.dashboardRequest('billing').then(data=>{if(!alive)return;RI.state.billing=Object.assign(RI.seedBilling('free'),data);if(['current','plans'].includes(tab))paint();}).catch(e=>{if(alive)RI.toast(e.message,{kind:'error'});});return()=>{alive=false;historyOff?.();};
 }});
})();
